/** Portable icon data or a React icon component. No markup strings are parsed. */
export function ChartIconView({ icon }: { icon: unknown }) {
  if (isChartIcon(icon)) {
    return (
      <svg
        viewBox={icon.viewBox ?? "0 0 24 24"}
        fill="none"
        stroke="currentColor"
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
        width="1em"
        height="1em"
        aria-hidden="true"
        focusable="false"
      >
        {icon.paths.map((d, index) => (
          <path key={index} d={d} />
        ))}
      </svg>
    );
  }
  const Icon = icon as React.ComponentType<{ className?: string }>;
  return <Icon />;
}

